import Foundation
import os.log

private let log = Logger(subsystem: "com.nomily.app.ios", category: "a1.credential")

// MARK: - DingTalk A1 device credential
//
// ## Why this type exists at all
//
// Every other recorder card we support can be driven with **protocol knowledge alone**:
// D·NOTE's pairing ID is generated by us, TicNote's Wi-Fi password is derived from the
// serial number. The DingTalk A1 is different — `0x0133` authenticates with
//
//     token = AES-128-CBC(key = ASCII(secret[0..16]), iv = key, pt = the device's 32-char random)
//
// and that `secret` is a **device-level credential minted by DingTalk when the card is
// bound to an account**. It is not derived from the SN, the DID or the MAC (three separate
// attempts, see the A1 reverse-engineering notes §3.1), it is never sent over
// BLE (§3.3), and one card's secret answers `501` on another card.
//
// So "using an A1 without DingTalk" always has exactly one unavoidable step: obtain the
// secret **once**, from a session that is allowed to see it. After that every connection
// is fully offline — the official app is not involved at runtime.
//
// ## What Nomily's job is
//
// Not to remove that step (it cannot be removed), but to shrink it from
// *"run a Python script, find the JSON, copy a file to the phone"* to
// *"paste one block of text"*. That block is what `parse(pasted:)` accepts, and
// `nomily-a1://` exists so a QR code or a link can carry the same payload later.
//
// ## Storage rules
//
// The secret is a credential, so it lives in the **Keychain** (`SecretStore`), never in
// `config.json`. `config.json` only ever learns the *SN* and a masked tail for display.
// This mirrors what `ConfigService` already does for provider API keys.

struct DingTalkA1Credential: Codable, Equatable {

    /// Device serial, e.g. `2010A1K262001N000655`. Also the advertising payload's tail.
    var sn: String
    /// `did` — the device id string (e.g. `1046161310`), **not** the BLE MAC.
    var deviceId: String
    /// The tenant the card is bound to. Required by both `0x0008` and `0x0133`.
    var corpId: String
    /// 32 hex characters. The AES key is its **first 16 ASCII characters** — do not hex-decode it.
    var secret: String

    var mac: String?
    var nick: String?
    /// Reported by the card in `0x0132` as `version`; only used for display.
    var firmware: String?

    /// Values the PC client uses. They are part of the authentication material as much as
    /// the token is (`0x0133` is rejected when `model` disagrees), so they are stored per card
    /// rather than hard-coded at the call site.
    var model: String = "Windows_A1_Client"
    var sdkVersion: String = "V2.1.3"

    var isValid: Bool {
        !deviceId.isEmpty && !corpId.isEmpty && secret.count >= 16
    }

    /// What the UI may show. Never render `secret` itself.
    var maskedSecret: String {
        guard secret.count >= 8 else { return "—" }
        return "••••" + secret.suffix(4)
    }

    /// Human name for lists: the card's own nickname, else the SN.
    var displayName: String {
        if let nick, !nick.isEmpty { return nick }
        return sn.isEmpty ? deviceId : sn
    }

    enum CodingKeys: String, CodingKey {
        case sn
        case deviceId = "device_id"
        case corpId = "corp_id"
        case secret
        case mac
        case nick
        case firmware
        case model
        case sdkVersion = "sdk_ver"
    }

    // MARK: Parsing

    /// Everything `parse` understands, for the footer of the import sheet.
    static let acceptedFormats = "nomily-a1://…  ·  JSON  ·  key=value lines"

    /// Registered in `Info.plist` (`CFBundleURLTypes`), so a scanned QR code or a tapped
    /// link can open the app straight into "import this card".
    static let urlScheme = "nomily-a1"

    init(sn: String, deviceId: String, corpId: String, secret: String,
         mac: String? = nil, nick: String? = nil, firmware: String? = nil,
         model: String = "Windows_A1_Client", sdkVersion: String = "V2.1.3") {
        self.sn = sn
        self.deviceId = deviceId
        self.corpId = corpId
        self.secret = secret
        self.mac = mac
        self.nick = nick
        self.firmware = firmware
        self.model = model
        self.sdkVersion = sdkVersion
    }

    enum ParseError: LocalizedError {
        case empty
        case notRecognised
        case missing(String)

        var errorDescription: String? {
            switch self {
            case .empty:
                return "Nothing was pasted."
            case .notRecognised:
                return "This doesn't look like a DingTalk A1 credential block. Paste the whole line the extractor printed."
            case .missing(let field):
                return "The pasted block is missing \(field)."
            }
        }
    }

    /// Accepts the three shapes the Mac-side extractor can print:
    ///
    /// 1. `nomily-a1://<base64(JSON)>` — one line, no escaping to worry about,
    ///    can go through a QR code or a chat message unmodified;
    /// 2. the raw JSON the extractor writes (`{"sn":…,"device_secret":…}`);
    /// 3. `key: value` / `key=value` lines, for anyone who copied the fields by hand.
    ///
    /// All three end in the same `DingTalkA1Credential`; keeping the parser tolerant is the
    /// whole point of the feature ("it shouldn't be this complicated just to get a secret").
    static func parse(pasted raw: String) throws -> DingTalkA1Credential {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { throw ParseError.empty }

        if text.lowercased().hasPrefix("nomily-a1://") {
            var body = String(text.dropFirst("nomily-a1://".count))
            // The canonical link form (`nomily-a1://import/<base64url>`) is what the extractor
            // prints and what a QR code carries. Accepting it here means "one link shape
            // everywhere", instead of the paste box and the camera quietly taking different
            // formats — which is how the wrong-secret bug would get a second chance.
            if body.lowercased().hasPrefix("import/") {
                body = String(body.dropFirst("import/".count))
            }
            guard let data = decodeBase64(body),
                  let json = String(data: data, encoding: .utf8)
            else { throw ParseError.notRecognised }
            return try parse(jsonBlock: json)
        }

        if text.hasPrefix("{") {
            return try parse(jsonBlock: text)
        }

        return try parseKeyValue(text)
    }

    /// QR code / deep-link entry point: `nomily-a1://import/<base64url>`.
    ///
    /// ## Why the payload sits in the *path*, and in **url-safe** base64
    ///
    /// Two independent traps, both silent:
    ///
    /// 1. `URL` treats the authority component (`scheme://` **host**) as case-insensitive and
    ///    may fold it to lowercase on the way back out of `absoluteString`. Standard base64 is
    ///    case-**sensitive**, so a payload in the host decodes to garbage — with no error,
    ///    because a wrong 32-byte secret still "decodes fine" and only surfaces later as `501`.
    /// 2. Standard base64 contains `/`, which would split into path segments.
    ///
    /// Putting a `import/` segment first and encoding the JSON url-safe (no `+`, `/`, `=`)
    /// removes both. The parser still accepts the plain `nomily-a1://<base64>` form, because
    /// that is what `--copy` puts on the clipboard.
    static func parse(link url: URL) throws -> DingTalkA1Credential {
        var text = url.absoluteString.trimmingCharacters(in: .whitespacesAndNewlines)
        guard text.lowercased().hasPrefix(urlScheme) else { throw ParseError.notRecognised }
        text = String(text.dropFirst(urlScheme.count))
        while text.hasPrefix(":") || text.hasPrefix("/") { text.removeFirst() }
        if text.lowercased().hasPrefix("import/") {
            text = String(text.dropFirst("import/".count))
        }
        guard let decoded = text.removingPercentEncoding, !decoded.isEmpty else {
            throw ParseError.notRecognised
        }
        return try parse(pasted: "\(urlScheme)://\(decoded)")
    }

    /// One entry point for text that came from *anywhere* — a paste box, a camera, a tapped
    /// link. Callers shouldn't have to know which of the three shapes they're holding.
    static func parse(scanned raw: String) throws -> DingTalkA1Credential {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        if text.lowercased().hasPrefix(urlScheme), let url = URL(string: text) {
            return try parse(link: url)
        }
        return try parse(pasted: text)
    }

    /// The form a QR code should carry: one line, URL-safe, no escaping needed.
    ///
    /// `sortedKeys` so the output is byte-identical to what the Mac-side `a1qr.swift` emits —
    /// that makes "did both sides build the same payload" a `==` instead of a field-by-field
    /// comparison, which is the only cheap way to keep the two encoders from drifting.
    var qrPayload: String {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        guard let data = try? encoder.encode(self) else { return "" }
        let urlSafe = data.base64EncodedString()
            .replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "=", with: "")
        return "\(Self.urlScheme)://import/\(urlSafe)"
    }

    /// Standard **and** url-safe base64, padded or unpadded.
    ///
    /// The first version decoded with `options: .ignoreUnknownCharacters`, which silently
    /// **drops** `-` and `_` instead of mapping them back to `+` and `/` — a url-safe payload
    /// then decodes to well-formed nonsense. Normalising first is what makes both forms work.
    private static func decodeBase64(_ body: String) -> Data? {
        var normalized = body
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "-", with: "+")
            .replacingOccurrences(of: "_", with: "/")
        while normalized.count % 4 != 0 { normalized += "=" }
        return Data(base64Encoded: normalized)
            ?? Data(base64Encoded: body, options: .ignoreUnknownCharacters)
    }

    private static func parse(jsonBlock: String) throws -> DingTalkA1Credential {
        guard let data = jsonBlock.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        else { throw ParseError.notRecognised }

        // The extractor writes snake_case (it is a Python tool); hand-written blocks tend to
        // use camelCase. Accept both rather than making the user care.
        func value(_ keys: [String]) -> String? {
            for key in keys {
                if let s = object[key] as? String, !s.isEmpty { return s }
                if let n = object[key] as? NSNumber { return n.stringValue }
            }
            return nil
        }

        guard let secret = value(["device_secret", "deviceSecret", "secret"]),
              secret.count >= 16
        else { throw ParseError.missing("device_secret") }
        guard let did = value(["device_id", "deviceId", "did"])
        else { throw ParseError.missing("device_id") }
        guard let corp = value(["corp_id", "corpId"])
        else { throw ParseError.missing("corp_id") }

        return DingTalkA1Credential(
            sn: value(["sn", "serial", "serial_number"]) ?? "",
            deviceId: did,
            corpId: corp,
            secret: secret,
            mac: value(["device_mac", "deviceMac", "mac"]),
            nick: value(["device_nick", "deviceNick", "nick", "name"]),
            firmware: value(["firmware", "version"]),
            model: value(["model"]) ?? "Windows_A1_Client",
            sdkVersion: value(["sdk_ver", "sdkVersion", "sdk_version"]) ?? "V2.1.3"
        )
    }

    private static func parseKeyValue(_ text: String) throws -> DingTalkA1Credential {
        var fields: [String: String] = [:]
        for line in text.split(whereSeparator: \.isNewline) {
            let parts = line.split(separator: "=", maxSplits: 1).count == 2
                ? line.split(separator: "=", maxSplits: 1)
                : line.split(separator: ":", maxSplits: 1)
            guard parts.count == 2 else { continue }
            let key = parts[0].trimmingCharacters(in: .whitespaces)
                .lowercased().replacingOccurrences(of: "-", with: "_")
            let value = parts[1].trimmingCharacters(in: .whitespaces)
            fields[key] = value
        }
        func pick(_ keys: [String]) -> String? {
            for key in keys where fields[key] != nil { return fields[key] }
            return nil
        }
        guard let secret = pick(["device_secret", "secret"]), secret.count >= 16 else {
            throw ParseError.missing("device_secret")
        }
        guard let did = pick(["device_id", "did", "deviceid"]) else {
            throw ParseError.missing("device_id")
        }
        guard let corp = pick(["corp_id", "corpid"]) else {
            throw ParseError.missing("corp_id")
        }
        return DingTalkA1Credential(
            sn: pick(["sn", "serial"]) ?? "",
            deviceId: did,
            corpId: corp,
            secret: secret,
            mac: pick(["device_mac", "mac"]),
            nick: pick(["device_nick", "nick", "name"]),
            model: pick(["model"]) ?? "Windows_A1_Client",
            sdkVersion: pick(["sdk_ver", "sdkversion"]) ?? "V2.1.3"
        )
    }

    /// The one-line form the extractor prints and the sheet can hand back out
    /// (e.g. to move a card to another phone). Contains the secret — treat like a password.
    var shareableLine: String {
        guard let data = try? JSONEncoder().encode(self) else { return "" }
        return "nomily-a1://" + data.base64EncodedString()
    }
}

// MARK: - Store

/// Keychain-backed list of A1 credentials, keyed by **SN** (falling back to the device id
/// when a card has no readable SN).
///
/// Stored as one JSON array in a single Keychain slot rather than one slot per card:
/// the number of A1s a person owns is tiny, and a single slot keeps `SecretStore` from
/// needing a dynamically-named account per device (which it deliberately does not support —
/// its `Slot` enum is the complete list of secrets by design).
enum DingTalkA1CredentialStore {

    private static let slot = SecretStore.Slot.dingTalkA1

    /// All known cards, newest write last.
    static func all() -> [DingTalkA1Credential] {
        guard let raw = SecretStore.load(slot),
              let data = raw.data(using: .utf8),
              let list = try? JSONDecoder().decode([DingTalkA1Credential].self, from: data)
        else { return [] }
        return list
    }

    /// Insert or replace by identity: same SN wins, otherwise same device id.
    ///
    /// ⚠️ Replacement rather than append is deliberate: re-importing a card after the
    /// seller unbinds it yields a **new** secret for the same hardware, and keeping both
    /// would make "which one authenticates" a coin flip (the stale one answers `501`).
    static func save(_ credential: DingTalkA1Credential) {
        var list = all()
        if let index = list.firstIndex(where: { matches($0, credential) }) {
            list[index] = credential
        } else {
            list.append(credential)
        }
        persist(list)
        log.info("stored A1 credential sn=\(credential.sn, privacy: .public) total=\(list.count, privacy: .public)")
    }

    static func remove(_ credential: DingTalkA1Credential) {
        persist(all().filter { !matches($0, credential) })
    }

    static func removeAll() {
        SecretStore.save(nil, to: slot)
    }

    /// Lookup used at connect time. Matching is **by SN first** (the advertisement carries the
    /// SN's last 4 digits, see `DingTalkA1Spec.parseAdvertisement`) and by device id second,
    /// because a card that has never been scanned has no SN on the phone yet.
    static func credential(sn: String?, deviceId: String?) -> DingTalkA1Credential? {
        let list = all()
        if let sn, !sn.isEmpty,
           let hit = list.first(where: { $0.sn.caseInsensitiveCompare(sn) == .orderedSame }) {
            return hit
        }
        if let deviceId, !deviceId.isEmpty,
           let hit = list.first(where: { $0.deviceId == deviceId }) {
            return hit
        }
        return nil
    }

    /// Only card, used when the advertisement gave us nothing usable.
    static var single: DingTalkA1Credential? {
        let list = all()
        return list.count == 1 ? list[0] : nil
    }

    /// Lookup for the scan path.
    ///
    /// The advertisement only carries the **last four characters** of the SN (`"0655"`), so an
    /// exact match would never hit. Matching the tail is safe here because the caller has
    /// already filtered to "this is an A1"; the worst case with two cards ending in the same
    /// four digits is an authentication attempt that answers `501`, after which the link falls
    /// back to "the only card on file" or asks the user to import it.
    static func credential(matchingTail tail: String?) -> DingTalkA1Credential? {
        guard let tail, !tail.isEmpty else { return nil }
        let list = all()
        if let hit = list.first(where: { $0.sn.hasSuffix(tail) }) { return hit }
        return nil
    }

    private static func matches(_ a: DingTalkA1Credential, _ b: DingTalkA1Credential) -> Bool {
        if !a.sn.isEmpty, !b.sn.isEmpty { return a.sn.caseInsensitiveCompare(b.sn) == .orderedSame }
        return a.deviceId == b.deviceId
    }

    private static func persist(_ list: [DingTalkA1Credential]) {
        guard !list.isEmpty else {
            SecretStore.save(nil, to: slot)
            return
        }
        guard let data = try? JSONEncoder().encode(list),
              let text = String(data: data, encoding: .utf8)
        else { return }
        SecretStore.save(text, to: slot)
    }
}
